INSERT INTO `blogs_pages` VALUES (1,'uploads/blog_pages/1767365343941.png','{\"de\":\"Unsere Blogs\",\"en\":\"Our Blog\",\"fr\":\"Nos Blogs\",\"it\":\"I Nostri Blog\",\"ar\":\"مدونتنا\"}','{\"de\":\"Einblicke, Tipps und Geschichten\",\"en\":\"Insights, Tips, and Stories\",\"fr\":\"Conseils, Astuces et Récits\",\"it\":\"Approfondimenti, Consigli e Storie\",\"ar\":null}','{\"de\":\"Tipps und Lösungen rund um Pflege, Reparatur und Services für Ihr Zuhause.\",\"en\":\"Tips, guides, and smart solutions to keep your home in top condition.\",\"fr\":\"Conseils et solutions pratiques pour l’entretien de votre maison.\",\"it\":\"Consigli e soluzioni intelligenti per la cura della tua casa.\",\"ar\":\"نصائح، إرشادات، وحلول ذكية تساعدك تحافظ على بيتك بأفضل حالة.\"}',NULL,'{\"de\":\"Zeigen Sie den letzten Blog\",\"en\":\"Show the last blog\",\"fr\":\"Afficher le dernier blog\",\"it\":\"Mostra l\'ultimo blog\",\"ar\":null}','{\"de\":\"Partnerschaft mit AuftragKompass, Geschäftspartnerschaft Umzugsdienstleistungen, zuverlässige Umzugspartner, Dienstleistungspartnerschaft, Umzugs- und Reinigungspartnerschaft Schweiz, Zusammenarbeit mit AuftragKompass, AuftragKompass Netzwerk beitreten, Geschäftsausbau Umzug und Reinigung, vertrauenswürdige Umzugs- und Reinigungspartner, Partnerschaftsmöglichkeiten Schweiz, Netzwerk zuverlässiger Umzugsunternehmen, geschäftliche Zusammenarbeit im Bereich Umzug und Reinigung, hochwertige Umzugsdienstleistungen anbieten, innovative Umzugs- und Reinigungslösungen, strategische Geschäftspartnerschaften Schweiz\",\"en\":\"partner with AuftragKompass, business partnership moving services, reliable moving partners, services partnership, moving and cleaning partnership Switzerland, collaborate with AuftragKompass, join AuftragKompass network, business expansion moving and cleaning, trusted moving and cleaning partners, partnership opportunities Switzerland, network of reliable movers, business collaboration in moving and cleaning, offer top-quality moving services, innovative moving and cleaning solutions, strategic business partnerships Switzerland\",\"fr\":\"partenariat avec AuftragKompass, partenariat commercial services de déménagement, partenaires de déménagement fiables, partenariat de services, partenariat déménagement et nettoyage en Suisse, collaborer avec AuftragKompass, rejoindre le réseau AuftragKompass, expansion commerciale déménagement et nettoyage, partenaires de déménagement et nettoyage de confiance, opportunités de partenariat en Suisse, réseau de déménageurs fiables, collaboration commerciale dans le déménagement et le nettoyage, offrir des services de déménagement de haute qualité, solutions innovantes de déménagement et de nettoyage, partenariats commerciaux stratégiques en Suisse\",\"it\":\"collaborare con AuftragKompass, partnership commerciale servizi di trasloco, partner di trasloco affidabili, partnership di servizi, partnership traslochi e pulizie in Svizzera, collaborare con AuftragKompass, entrare nella rete AuftragKompass, espansione aziendale traslochi e pulizie, partner affidabili per traslochi e pulizie, opportunità di partnership in Svizzera, rete di traslocatori affidabili, collaborazione commerciale nel settore traslochi e pulizie, offrire servizi di trasloco di alta qualità, soluzioni innovative per traslochi e pulizie, partnership commerciali strategiche in Svizzera\",\"ar\":\"الشراكة مع AuftragKompass، شراكة أعمال في خدمات النقل، شركاء نقل موثوقون، شراكة خدمات، شراكة النقل والتنظيف في سويسرا، التعاون مع AuftragKompass، الانضمام إلى شبكة AuftragKompass، توسيع الأعمال في النقل والتنظيف، شركاء نقل وتنظيف موثوقون، فرص شراكة في سويسرا، شبكة من شركات النقل الموثوقة، تعاون تجاري في النقل والتنظيف، تقديم خدمات نقل عالية الجودة، حلول نقل وتنظيف مبتكرة، شراكات أعمال استراتيجية في سويسرا\"}','{\"de\":\"Smarte und schnelle Lösungen für Ihr Zuhause.\",\"en\":\"Smart and fast home solutions – because your home deserves the best.\",\"fr\":\"Des solutions intelligentes et rapides pour votre maison.\",\"it\":\"Soluzioni intelligenti e rapide per la tua casa.\",\"ar\":\"نقدّم حلول منزلية ذكية وسريعة، لأن راحة بيتك تستحق الأفضل.\"}','{\"de\":\"Arbeiten Sie mit AuftragKompass zusammen und erweitern Sie Ihr Geschäft. Wir suchen zuverlässige Partner für Umzugs- und Reinigungsdienste in der ganzen Schweiz. Werden Sie Teil unseres vertrauenswürdigen Netzwerks und bieten Sie gemeinsam hochwertige Lösungen an.\",\"en\":\"Collaborate with AuftragKompass and grow your business. We are looking for reliable partners in moving and cleaning services across Switzerland. Join our trusted network and deliver top-quality solutions together.\",\"fr\":\"Collaborez avec AuftragKompass et développez votre activité. Nous recherchons des partenaires fiables dans les services de déménagement et de nettoyage à travers la Suisse. Rejoignez notre réseau de confiance et offrez ensemble des solutions de haute qualité.\",\"it\":\"Collabora con AuftragKompass e fai crescere il tuo business. Cerchiamo partner affidabili nei servizi di trasloco e pulizia in tutta la Svizzera. Unisciti alla nostra rete di fiducia e offriamo insieme soluzioni di alta qualità.\",\"ar\":\"تعاون مع AuftragKompass ووسّع نشاطك التجاري. نحن نبحث عن شركاء موثوقين في خدمات النقل والتنظيف داخل سويسرا. انضم إلى شبكتنا الموثوقة وقدّم حلولًا عالية الجودة معنا.\"}',NULL,'2026-01-02 14:49:03');
