INSERT INTO `contact_pages` VALUES (1,'{\"de\":\"Kontaktieren Sie uns\",\"en\":\"Contact Us\",\"fr\":\"Contactez-nous\",\"it\":\"Contattaci\",\"ar\":\"اتصل بنا\"}','{\"de\":\"Lassen Sie uns in Verbindung treten – Wir sind hier, um zu helfen!\",\"en\":\"Let’s Connect – We’re Here to Help!\",\"fr\":\"Contactez-nous – Nous sommes là pour vous aider !\",\"it\":\"Mettiamoci in contatto – Siamo qui per aiutarti!\",\"ar\":null}','{\"de\":\"Wir freuen uns auf Ihre Nachricht! Wenn Sie Fragen haben, Unterstützung benötigen oder mehr über die Dienstleistungen von AuftragKompass erfahren möchten, kontaktieren Sie uns gerne. Unser Team hilft Ihnen schnell und zuverlässig weiter.\",\"en\":\"We’re happy to hear from you! If you have any questions, need assistance, or would like to learn more about AuftragKompass services, feel free to contact us. Our team is ready to support you and respond as quickly as possible.\",\"fr\":\"Nous sommes ravis de vous entendre ! Si vous avez des questions, besoin d’aide ou souhaitez en savoir plus sur les services d’AuftragKompass, n’hésitez pas à nous contacter. Notre équipe est à votre disposition pour vous répondre rapidement.\",\"it\":\"Siamo lieti di sentirti! Se hai domande, hai bisogno di assistenza o desideri maggiori informazioni sui servizi di AuftragKompass, non esitare a contattarci. Il nostro team è pronto ad aiutarti e a rispondere rapidamente.\",\"ar\":\"يسعدنا تواصلك معنا! إذا كان لديك أي استفسار، تحتاج إلى مساعدة، أو ترغب في معرفة المزيد عن خدمات AuftragKompass، لا تتردد في التواصل معنا. فريقنا جاهز للرد على جميع أسئلتك ومساعدتك في أقرب وقت.\"}','uploads/contact_pages/1767365221918.jpg','{\"de\":\"Bleiben Sie in Kontakt\",\"en\":\"Keep in Touch\",\"fr\":\"Restez en contact\",\"it\":\"Resta in contatto\",\"ar\":\"أبق على اتصال\"}','{\"de\":\"Bleiben Sie mit uns in Verbindung!\",\"en\":\"Stay Connected with Us!\",\"fr\":\"Restez connecté avec nous !\",\"it\":\"Rimani connesso con noi!\",\"ar\":\"ابقَ على اتصال بنا!\"}','{\"de\":\"Unsere Informationen\",\"en\":\"Our Information\",\"fr\":\"Nos informations\",\"it\":\"Le nostre informazioni\",\"ar\":\"معلوماتنا\"}','{\"de\":\"Kontaktieren Sie uns\",\"en\":\"Contact Auftragkompass: Your Questions Are Welcome\",\"fr\":\"Contactez-nous\",\"it\":\"Contatta Auftragkompass: Le Tue Domande Sono Benvenute\",\"ar\":\"للتواصل مع Auftragkompass: نرحب بأسئلتكم\"}','{\"de\":\"Kontaktieren Sie Auftragkompass: Ihre Fragen sind willkommen\",\"en\":\"Contact Auftragkompass: Your Questions Are Welcome\",\"fr\":\"Contactez Auftragkompass: Vos Questions Sont Les Bienvenue\",\"it\":\"Contatta Auftragkompass: Le Tue Domande Sono Benvenute\",\"ar\":\"للتواصل مع Auftragkompass: نرحب بأسئلتكم\"}','{\"de\":\"Haben Sie Fragen? Kontaktieren Sie uns bei Auftragkompassfür Informationen zu unseren Umzugs- und Reinigungsdiensten. Wir sind hier, um Ihnen zu helfen!\",\"en\":\"Do you have questions? Contact us at Auftragkompassfor information about our moving and cleaning services. We are here to assist you\",\"fr\":\"Avez-vous des questions ? Contactez-nous chez Auftragkompass pour obtenir des informations sur nos services de déménagement et nettoyage. Nous sommes là pour vous aider\",\"it\":\"Hai domande? Contattaci presso Auftragkompass per informazioni sui nostri servizi di traslochi e pulizie. Siamo qui per aiutarti\",\"ar\":\"هل لديك أي استفسارات؟ تواصل معنا في Auftragkompassللحصول على معلومات حول خدمات النقل والتنظيف التي نقدمها. نحن هنا لمساعدتك.\"}','2025-01-02 13:01:17','2026-01-05 20:40:48');
/*!40000 ALTER TABLE `contact_pages` ENABLE KEYS */;
UNLOCK TABLES;

