INSERT INTO `faq_pages` VALUES (1,'{\"de\":\"uploads\\/faq\\/1767365021596.png\",\"en\":\"uploads\\/faq\\/1767365021490.png\",\"fr\":\"uploads\\/faq\\/1767365021214.png\",\"it\":\"uploads\\/faq\\/1767365021338.png\",\"ar\":\"uploads\\/faq\\/1767365021574.png\"}','{\"de\":\"FAQs\",\"en\":\"FAQs\",\"fr\":\"FAQ\",\"it\":\"FAQ\",\"ar\":\"الأسئلة الشائعة\"}','{\"de\":\"Häufig gestellte Fragen – Alles, was Sie über die Dienstleistungen von AuftragKompass wissen müssen\",\"en\":\"Frequently Asked Questions – Everything You Need to Know About AuftragKompass Services\",\"fr\":\"Foire aux questions – Tout ce que vous devez savoir sur les services d’AuftragKompass\",\"it\":\"Domande frequenti – Tutto quello che devi sapere sui servizi di AuftragKompass\",\"ar\":\"الأسئلة الشائعة – كل ما تحتاج معرفته عن خدمات AuftragKompass\"}','{\"de\":\"Haben Sie Fragen? Wir haben die Antworten!\",\"en\":\"Got Questions? We’ve Got Answers!\",\"fr\":\"Vous avez des questions ? Nous avons les réponses !\",\"it\":\"Hai domande? Abbiamo le risposte!\",\"ar\":\"هل لديك أسئلة؟ لدينا إجابات!\"}','{\"de\":\"JETZT FRAGEN\",\"en\":\"ASK NOW\",\"fr\":\"DEMANDEZ MAINTENANT\",\"it\":\"CHIEDI ORA\",\"ar\":null}','{\"de\":\"Lassen Sie sich Ihre Fragen sofort beantworten\",\"en\":\"Get Your Questions Answered Instantly\",\"fr\":\"Obtenez des réponses à vos questions instantanément.\",\"it\":\"Ottieni risposte alle tue domande all\'istante\",\"ar\":null}','{\"de\":\"Umzug FAQ, Reinigungsservices FAQ, FAQ-Seite, AuftragKompass Services FAQ, Tipps und Antworten zum Umzug, Informationen über Umzugsfirmen, Reinigungsfirmen, Fragen zu Umzugsservices, Antworten zu Reinigungsdiensten, FAQ zur umweltfreundlichen Reinigung, Informationen zur Reinigung nach dem Umzug, zuverlässige Umzugs- und Reinigungsfirmen, professionelle Reinigungs-FAQ, Fragen zu Verpackung und Transport, Servicekosten, beste Reinigungs-Tipps und Tricks, Umzugs-Checklisten-Fragen, Kundenanfragen AuftragKompass, Fragen vor dem Umzug, zuverlässiger Servicepartner\",\"en\":\"Moving FAQ, cleaning services FAQ, FAQ page, AuftragKompass services FAQ, moving tips and answers, information about moving companies, cleaning companies, questions about moving services, answers about cleaning services, eco-friendly cleaning FAQ, post-move cleaning information, trusted moving and cleaning companies, professional cleaning FAQ, packing and moving questions, service costs, best cleaning tips and tricks, moving checklist questions, AuftragKompass customer inquiries, questions before moving, trusted service partner\",\"fr\":\"FAQ déménagement, FAQ services de nettoyage, page FAQ, FAQ des services AuftragKompass, conseils et réponses sur le déménagement, informations sur les entreprises de déménagement, entreprises de nettoyage, questions sur les services de déménagement, réponses sur les services de nettoyage, FAQ sur le nettoyage écologique, informations sur le nettoyage après déménagement, entreprises de déménagement et de nettoyage fiables, FAQ nettoyage professionnel, questions sur l’emballage et le transport, coûts des services, meilleures astuces de nettoyage, questions sur la checklist de déménagement, demandes clients AuftragKompass, questions avant déménagement, partenaire de services fiable\",\"it\":\"FAQ trasloco, FAQ servizi di pulizia, pagina FAQ, FAQ servizi AuftragKompass, consigli e risposte sul trasloco, informazioni sulle aziende di traslochi, imprese di pulizia, domande sui servizi di trasloco, risposte sui servizi di pulizia, FAQ sulla pulizia ecologica, informazioni sulla pulizia post-trasloco, aziende di trasloco e pulizia affidabili, FAQ pulizia professionale, domande su imballaggio e trasporto, costi dei servizi, migliori consigli e trucchi di pulizia, domande sulla checklist del trasloco, richieste clienti AuftragKompass, domande prima del trasloco, partner di servizi affidabile\",\"ar\":\"أسئلة شائعة حول الانتقال، أسئلة شائعة حول خدمات التنظيف، صفحة الأسئلة الشائعة، أسئلة شائعة حول خدمات AuftragKompass، نصائح وإجابات حول الانتقال، معلومات عن شركات النقل، شركات التنظيف، أسئلة حول خدمات الانتقال، إجابات عن خدمات التنظيف، أسئلة شائعة حول التنظيف الصديق للبيئة، معلومات عن التنظيف بعد الانتقال، شركات نقل وتنظيف موثوقة، أسئلة شائعة حول التنظيف الاحترافي، أسئلة حول التعبئة والنقل، تكاليف الخدمات، أفضل نصائح وحيل التنظيف، أسئلة حول قائمة التحقق من الانتقال، استفسارات عملاء AuftragKompass، أسئلة قبل الانتقال، شريك خدمات موثوق\"}','{\"de\":\"AuftragKompass verbindet Sie mit zuverlässigen Handwerkern für alle Haushaltsservices.\",\"en\":\"AuftragKompass connects you with trusted home service professionals through a simple and secure platform.\",\"fr\":\"AuftragKompass vous met en relation avec des professionnels fiables pour tous les services de la maison.\",\"it\":\"AuftragKompass ti collega a professionisti affidabili per tutti i servizi domestici.\",\"ar\":\"منصة AuftragKompass تجمع كل خدمات المنزل وتربطك بحرفيين موثوقين بخطوات سهلة وآمنة.\"}','2025-01-01 15:30:14','2026-01-02 14:43:41');
/*!40000 ALTER TABLE `faq_pages` ENABLE KEYS */;
