INSERT INTO `faqs` VALUES (4,'{\"de\":\"Wie kann ich eine Dienstleistung bei AuftragKompass anfragen?\",\"en\":\"How can I request a service from AuftragKompass?\",\"fr\":\"Comment demander un service via AuftragKompass ?\",\"it\":\"Come posso richiedere un servizio su AuftragKompass?\",\"ar\":\"كيف يمكنني طلب خدمة من AuftragKompass؟\"}','{\"de\":\"Wählen Sie den gewünschten Service aus, geben Sie die Details ein, und wir vermitteln Ihnen den passenden Fachbetrieb.\",\"en\":\"Simply select the service, fill in your request details, and we will connect you with the best suitable professional.\",\"fr\":\"Choisissez le service souhaité, remplissez les détails, et nous vous mettrons en relation avec le bon prestataire.\",\"it\":\"Seleziona il servizio, inserisci i dettagli della richiesta e ti metteremo in contatto con il professionista giusto.\",\"ar\":\"اختر نوع الخدمة، املأ تفاصيل الطلب، وسيتم توجيهك لأفضل مقدم خدمة مناسب لاحتياجك.\"}','2025-01-02 12:28:28','2025-12-31 21:23:23'),(7,'{\"de\":\"Sind die Services für Privatpersonen und Unternehmen verfügbar?\",\"en\":\"Are services available for individuals and businesses?\",\"fr\":\"Les services sont-ils disponibles pour les particuliers et les entreprises ?\",\"it\":\"I servizi sono disponibili per privati e aziende?\",\"ar\":\"هل يمكن للأفراد والشركات استخدام AuftragKompass؟\"}','{\"de\":\"Ja, unsere Dienstleistungen stehen sowohl Privatkunden als auch Unternehmen zur Verfügung.\",\"en\":\"Yes, our services are available for private customers as well as businesses\",\"fr\":\"Oui, nos services sont destinés aux particuliers comme aux entreprises\",\"it\":\"Sì, i nostri servizi sono disponibili sia per privati che per aziende\",\"ar\":\"نعم، خدماتنا متاحة للأفراد، العائلات، والشركات.\"}','2025-01-03 04:38:12','2025-12-31 21:25:50'),(8,'{\"de\":\"Wie wird der Dienstleister ausgewählt?\",\"en\":\"How is the service provider selected?\",\"fr\":\"Comment le prestataire est-il sélectionné ?\",\"it\":\"Come viene selezionato il fornitore del servizio?\",\"ar\":\"كيف يتم اختيار الحرفي أو مقدم الخدمة؟\"}','{\"de\":\"Ihr Auftrag wird anhand von Serviceart und Standort an geprüfte Anbieter vermittelt.\",\"en\":\"We match your request with trusted professionals based on service type and location.\",\"fr\":\"Votre demande est transmise à des professionnels fiables selon le service et la localisation.\",\"it\":\"La richiesta viene abbinata a professionisti affidabili in base al servizio e alla zona.\",\"ar\":\"النظام يوجّه طلبك إلى مقدمي خدمات موثوقين بناءً على نوع الخدمة والموقع.\"}','2025-01-21 08:21:00','2025-12-31 21:28:15'),(9,'{\"de\":\"Ist AuftragKompass sicher?\",\"en\":\"Is AuftragKompass safe to use?\",\"fr\":\"AuftragKompass est-il sécurisé ?\",\"it\":\"AuftragKompass è sicuro?\",\"ar\":\"هل المنصة آمنة؟\"}','{\"de\":\"Ja, wir arbeiten ausschließlich mit zuverlässigen Partnern für eine sichere Abwicklung.\",\"en\":\"Yes, we work with reliable partners to ensure a safe and organized experience.\",\"fr\":\"Oui, nous collaborons avec des partenaires fiables pour une expérience sécurisée.\",\"it\":\"Sì, collaboriamo con partner affidabili per garantire un servizio sicuro.\",\"ar\":\"نعم، AuftragKompass يعتمد على شركاء موثوقين ويضمن تجربة منظمة وآمنة.\"}','2025-01-21 08:24:21','2025-12-31 21:30:18'),(10,'{\"de\":\"Kann ich meinen Auftrag verfolgen?\",\"en\":\"Can I track my service request?\",\"fr\":\"Puis-je suivre l’état de ma demande ?\",\"it\":\"Posso monitorare la mia richiesta?\",\"ar\":\"هل يمكن متابعة الطلب بعد إرساله؟\"}','{\"de\":\"Ja, Sie können den Status Ihres Auftrags jederzeit verfolgen.\",\"en\":\"Yes, you can follow the status of your request until completion.\",\"fr\":\"Oui, vous pouvez suivre votre demande jusqu’à sa réalisation.\",\"it\":\"Sì, puoi seguire lo stato della richiesta fino al completamento.\",\"ar\":\"نعم، يمكنك متابعة حالة الطلب خطوة بخطوة حتى تنفيذ الخدمة.\"}','2025-01-21 08:27:22','2025-12-31 21:32:21');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

