INSERT INTO `forms` VALUES (1,'{\"de\":\"Füllen Sie das Formular aus, um ein Angebot zu erhalten\",\"en\":\"Fill out the form to get an offer\",\"fr\":\"Remplissez le formulaire pour obtenir une offre\",\"it\":\"Compila il modulo per ricevere un’offerta\",\"ar\":\"املأ النموذج للحصول على عرض\"}','{\"de\":\"Persönliche Angaben\",\"en\":\"Personal Information\",\"fr\":\"Informations personnelles\",\"it\":\"Informazioni personali\",\"ar\":\"البيانات الشخصية\"}','{\"de\":\"Service informationen\",\"en\":\"Service Information\",\"fr\":\"Informations sur le service\",\"it\":\"Informazioni sul servizio\",\"ar\":\"معلومات الخدمة\"}','{\"de\":\"Dienstleistung auswählen\",\"en\":\"Select the service\",\"fr\":\"Sélectionner le service\",\"it\":\"Seleziona il servizio\",\"ar\":\"اختر الخدمة\"}','{\"de\":\"Nachname\",\"en\":\"Last Name\",\"fr\":\"Nom de famille\",\"it\":\"Cognome\",\"ar\":\"لقب العائلة\"}','{\"de\":\"Vorname\",\"en\":\"First Name\",\"fr\":\"Prénom\",\"it\":\"Nome\",\"ar\":\"الاسم الاول\"}','{\"de\":\"E-Mail\",\"en\":\"Email\",\"fr\":\"E-mail\",\"it\":\"Email\",\"ar\":\"البريد الالكتروني\"}','{\"de\":\"Telefonnummer\",\"en\":\"Phone Number\",\"fr\":\"Numéro de téléphone\",\"it\":\"Numero di telefono\",\"ar\":\"رقم موبايل\"}','{\"de\": \"Strasse\", \"en\": \"street\", \"fr\": \"rue\", \"it\": \"strada\"}','{\"de\": \"Stadt\", \"en\": \"City\", \"fr\": \"Ville\", \"it\": \"Città\"}','{\"de\": \"Anzahl der Zimmer\", \"en\": \"Rooms Number\", \"fr\": \"Nombre de pièces\", \"it\": \"Numero di stanze\"}','{\"de\": \"Etage\", \"en\": \"Floor\", \"fr\": \"Étage\", \"it\": \"piano\"}','{\"de\": \"Aufzugs\", \"en\": \"Elevator\", \"fr\": \"ascenseur\", \"it\": \"Ascensore\"}','{\"de\":\"Straße\",\"en\":\"street\",\"fr\":\"rue\",\"it\":\"strada\",\"ar\":\"الشارع\"}','{\"de\":\"Stadt\",\"en\":\"City\",\"fr\":\"ville\",\"it\":\"città\",\"ar\":\"الدولة\"}','{\"de\":\"Anzahl de Zimmer\",\"en\":\"Rooms Number\",\"fr\":\"Nombre de pièces\",\"it\":\"Numero di stanze\",\"ar\":\"عدد الغرف\"}','{\"de\":\"Etage\",\"en\":\"Floor\",\"fr\":\"étage\",\"it\":\"piano\",\"ar\":\"الدور\"}','{\"de\":\"Aufzugs\",\"en\":\"Elevator\",\"fr\":\"ascenseur\",\"it\":\"ascensore\",\"ar\":\"مصعد\"}','{\"de\":\"Datum\",\"en\":\"Date\",\"fr\":\"Date\",\"it\":\"Data\",\"ar\":\"التاريخ\"}','{\"de\":\"Anzahl der Angebote\",\"en\":\"Offers Number\",\"fr\":\"Nombre d\'offres\",\"it\":\"Numero di offerte\",\"ar\":\"رقم العرض\"}','{\"de\":\"Weitere Details\",\"en\":\"Other Details\",\"fr\":\"Autres détails\",\"it\":\"Altri dettagli\",\"ar\":\"تفاصيل اخري\"}','{\"de\":\"Bitte geben Sie keine Adressen oder Kontaktdaten in dieses Feld ein.\",\"en\":\"Please do not enter any addresses or contact details in this field.\",\"fr\":\"Veuillez ne pas entrer d’adresses ou de coordonnées dans ce champ.\",\"it\":\"Si prega di non inserire indirizzi o dettagli di contatto in questo campo.\",\"ar\":\"ارجوا عدم اضافة اي عنوان او بيانات في هذا الحقل\"}',NULL,'{\"de\":\"Füllen Sie das Formular aus und wir finden den passenden Fachbetrieb für Ihr Anliegen – schnell und unkompliziert.\",\"en\":\"Fill out the form and let us guide you to the right professional for your needs — quickly and easily.\",\"fr\":\"Remplissez le formulaire et nous vous orienterons vers le professionnel adapté à votre besoin, simplement et rapidement.\",\"it\":\"Compila il modulo e ti guideremo verso il professionista giusto per le tue esigenze, in modo semplice e veloce.\",\"ar\":\"املأ النموذج الآن ودعنا نوجّهك لأفضل حرفي مناسب لاحتياجك، بخطوات سهلة وسريعة.\"}',NULL,'{\"de\":\"Danke\",\"en\":\"Thank you\",\"fr\":\"Merci\",\"it\":\"Grazie\",\"ar\":\"شكرا\"}','{\"de\":\"Ihr Formular wurde erfolgreich übermittelt\",\"en\":\"Your form was submitted successfully\",\"fr\":\"Votre formulaire a été soumis avec succès\",\"it\":\"Il tuo modulo è stato inviato con successo\",\"ar\":\"تم الارسال بنجاح\"}',NULL,'uploads/homes/1737480735720.jpg','{\"en\":\"Country\",\"de\":\"Land\",\"it\":\"paese\",\"fr\":\"pays\",\"ar\":\"المدينة\"}','{\"en\":\"Zipcode\",\"de\":\"Postleitzahl\",\"it\":\"codice postale\",\"fr\":\"code postal\",\"ar\":\"كود الدولة\"}','{\"en\":\"Country\",\"de\":\"Land\",\"it\":\"Paese\",\"fr\":\"Pays\"}','{\"en\":\"Zipcode\",\"de\":\"Postleitzahl\",\"it\":\"Codice postale\",\"fr\":\"Code postal\"}','2024-12-30 12:49:19','2026-09-30 22:52:59');
