INSERT INTO `page_comapnies` VALUES (1,'{\"de\":\"Vertrauenswürdige\",\"en\":\"Trusted Companies\",\"fr\":\"Entreprises Confiance\",\"it\":\"Aziende Fidate di Traslochi e Pulizie\",\"ar\":\"شركات موثوقة\"}','{\"de\":\"Partnerschaften mit den Besten für Ihre Bedürfnisse\",\"en\":\"Partnering with the Best for Your Needs\",\"fr\":\"Partenariats avec les meilleurs pour vos besoins\",\"it\":\"Collaboriamo con i migliori per le tue esigenze\",\"ar\":\"الشراكة مع الأفضل لتلبية احتياجاتك\"}','{\"de\":\"Wir arbeiten mit erstklassigen Umzugs- und Reinigungsunternehmen zusammen, um Ihnen zuverlässige, professionelle und erschwingliche Dienstleistungen zu bieten. Ob es sich um einen Wohnungsumzug, ein Bürorelocation oder eine Grundreinigung handelt – unsere Partner sind hier, um Ihr Leben einfacher zu machen.\",\"en\":\"We collaborate with top-rated moving and cleaning companies to bring you reliable, professional, and affordable services. Whether it’s a home move, office relocation, or deep cleaning, our partners are here to make your life easier.\",\"fr\":\"Nous collaborons avec des entreprises de déménagement et de nettoyage haut de gamme pour vous offrir des services fiables, professionnels et abordables. Que ce soit pour un déménagement résidentiel, une relocalisation de bureau ou un nettoyage en profondeur, nos partenaires sont là pour vous simplifier la vie.\",\"it\":\"Collaboriamo con aziende di traslochi e pulizie di alto livello per offrirti servizi affidabili, professionali e convenienti. Che si tratti di un trasloco domestico, di un trasferimento di ufficio o di una pulizia profonda, i nostri partner sono qui per rendere la tua vita più semplice.\",\"ar\":\"نتعاون مع أفضل شركات النقل والتنظيف لنقدم لكم خدمات موثوقة واحترافية وبأسعار معقولة. سواءً كان الأمر يتعلق بنقل منزل، أو نقل مكتب، أو تنظيف شامل، فإن شركاءنا هنا لتسهيل حياتكم.\"}','uploads//page_companies/1737638936745.png','{\"de\":\"Werden Sie Teil unserer vertrauenswürdigen Unternehmen\",\"en\":\"Search for the Service You Need to See Available Companies\",\"fr\":\"Rejoignez nos entreprises de confiance\",\"it\":\"Unisciti alle nostre aziende fidate\",\"ar\":\"ابحث عن الخدمة التي تحتاجها للاطلاع على الشركات المتاحة\"}','{\"de\":\"Top Unternehmen\",\"en\":\"Top Companies\",\"fr\":\"Meilleures Entreprises\",\"it\":\"Migliori Aziende\",\"ar\":\"أفضل الشركات\"}','{\"ar\":null}','{\"ar\":null}','2025-01-02 14:59:29','2025-12-30 22:47:42');
/*!40000 ALTER TABLE `page_comapnies` ENABLE KEYS */;
UNLOCK TABLES;

