INSERT INTO `question_options` VALUES (387,232,'{\"en\":\"Structural shell work\",\"de\":\"Rohbauarbeiten\",\"it\":\"Lavori di costruzione al grezzo\",\"fr\":\"Travaux de gros œuvre\",\"ar\":\"أعمال الهيكل الإنشائي\"}',NULL,1,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(388,232,'{\"en\":\"Masonry work\",\"de\":\"Maurerarbeiten\",\"it\":\"Lavori di muratura\",\"fr\":\"Travaux de maçonnerie\",\"ar\":\"أعمال المباني\"}',NULL,2,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(389,232,'{\"en\":\"Foundation work\",\"de\":\"Fundamentarbeiten\",\"it\":\"Lavori di fondazione\",\"fr\":\"Travaux de fondation\",\"ar\":\"أعمال الأساسات\"}',NULL,3,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(390,232,'{\"en\":\"Concrete work\",\"de\":\"Betonarbeiten\",\"it\":\"Lavori in calcestruzzo\",\"fr\":\"Travaux en béton\",\"ar\":\"أعمال الخرسانة\"}',NULL,4,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(391,232,'{\"en\":\"Several types of work\",\"de\":\"Mehrere Arbeiten\",\"it\":\"Più tipi di lavori\",\"fr\":\"Plusieurs types de travaux\",\"ar\":\"عدة أعمال\"}',NULL,5,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(392,232,'{\"en\":\"Other\",\"de\":\"Sonstiges\",\"it\":\"Altro\",\"fr\":\"Autre\",\"ar\":\"أخرى\"}',NULL,6,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(393,234,'{\"en\":\"New build – single-family house\",\"de\":\"Neubau eines Einfamilienhauses\",\"it\":\"Nuova costruzione – casa unifamiliare\",\"fr\":\"Construction neuve – maison individuelle\",\"ar\":\"بناء جديد – منزل لعائلة واحدة\"}',NULL,1,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(394,234,'{\"en\":\"New build – multi-family house\",\"de\":\"Neubau eines Mehrfamilienhauses\",\"it\":\"Nuova costruzione – condominio\",\"fr\":\"Construction neuve – immeuble collectif\",\"ar\":\"بناء جديد – مبنى متعدد الوحدات السكنية\"}',NULL,2,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(395,234,'{\"en\":\"Commercial building\",\"de\":\"Gewerbegebäude\",\"it\":\"Edificio commerciale\",\"fr\":\"Bâtiment commercial\",\"ar\":\"مبنى تجاري\"}',NULL,3,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(396,234,'{\"en\":\"Extension or addition\",\"de\":\"Anbau oder Erweiterung\",\"it\":\"Ampliamento o estensione\",\"fr\":\"Extension ou agrandissement\",\"ar\":\"ملحق أو توسعة\"}',NULL,4,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(397,234,'{\"en\":\"Conversion of an existing building\",\"de\":\"Umbau eines bestehenden Gebäudes\",\"it\":\"Ristrutturazione di un edificio esistente\",\"fr\":\"Transformation d’un bâtiment existant\",\"ar\":\"تعديل أو إعادة بناء مبنى قائم\"}',NULL,5,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(398,234,'{\"en\":\"Other\",\"de\":\"Sonstiges\",\"it\":\"Altro\",\"fr\":\"Autre\",\"ar\":\"أخرى\"}',NULL,6,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(399,236,'{\"en\":\"Up to 50 m²\",\"de\":\"Bis 50 m²\",\"it\":\"Fino a 50 m²\",\"fr\":\"Jusqu’à 50 m²\",\"ar\":\"حتى 50 م²\"}',NULL,1,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(400,236,'{\"en\":\"51–100 m²\",\"de\":\"51–100 m²\",\"it\":\"51–100 m²\",\"fr\":\"51–100 m²\",\"ar\":\"51–100 م²\"}',NULL,2,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(401,236,'{\"en\":\"101–150 m²\",\"de\":\"101–150 m²\",\"it\":\"101–150 m²\",\"fr\":\"101–150 m²\",\"ar\":\"101–150 م²\"}',NULL,3,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(402,236,'{\"en\":\"151–250 m²\",\"de\":\"151–250 m²\",\"it\":\"151–250 m²\",\"fr\":\"151–250 m²\",\"ar\":\"151–250 م²\"}',NULL,4,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(403,236,'{\"en\":\"251–500 m²\",\"de\":\"251–500 m²\",\"it\":\"251–500 m²\",\"fr\":\"251–500 m²\",\"ar\":\"251–500 م²\"}',NULL,5,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(404,236,'{\"en\":\"More than 500 m²\",\"de\":\"Mehr als 500 m²\",\"it\":\"Oltre 500 m²\",\"fr\":\"Plus de 500 m²\",\"ar\":\"أكثر من 500 م²\"}',NULL,6,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(405,236,'{\"en\":\"Not yet known\",\"de\":\"Noch nicht bekannt\",\"it\":\"Non ancora noto\",\"fr\":\"Pas encore connu\",\"ar\":\"غير معروف حتى الآن\"}',NULL,7,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(406,237,'{\"en\":\"Planning is still in progress\",\"de\":\"Planung läuft noch\",\"it\":\"La progettazione è ancora in corso\",\"fr\":\"La planification est encore en cours\",\"ar\":\"التخطيط ما زال قيد التنفيذ\"}',NULL,1,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(407,237,'{\"en\":\"Construction planning is complete\",\"de\":\"Bauplanung abgeschlossen\",\"it\":\"La progettazione è completata\",\"fr\":\"La planification de construction est terminée\",\"ar\":\"تم الانتهاء من تخطيط البناء\"}',NULL,2,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(408,237,'{\"en\":\"The site is prepared\",\"de\":\"Grundstück ist vorbereitet\",\"it\":\"Il terreno è preparato\",\"fr\":\"Le terrain est préparé\",\"ar\":\"تم تجهيز موقع البناء\"}',NULL,3,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(409,237,'{\"en\":\"Construction work has already started\",\"de\":\"Bauarbeiten haben bereits begonnen\",\"it\":\"I lavori sono già iniziati\",\"fr\":\"Les travaux ont déjà commencé\",\"ar\":\"بدأت أعمال البناء بالفعل\"}',NULL,4,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(410,237,'{\"en\":\"An existing building is to be extended or converted\",\"de\":\"Bestehendes Gebäude soll erweitert oder umgebaut werden\",\"it\":\"Un edificio esistente deve essere ampliato o ristrutturato\",\"fr\":\"Un bâtiment existant doit être agrandi ou transformé\",\"ar\":\"سيتم توسيع أو تعديل مبنى قائم\"}',NULL,5,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(411,238,'{\"en\":\"Yes, complete\",\"de\":\"Ja, vollständig\",\"it\":\"Sì, completi\",\"fr\":\"Oui, complets\",\"ar\":\"نعم، كاملة\"}',NULL,1,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(412,238,'{\"en\":\"Yes, partially\",\"de\":\"Ja, teilweise\",\"it\":\"Sì, parzialmente\",\"fr\":\"Oui, partiellement\",\"ar\":\"نعم، جزئيًا\"}',NULL,2,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(413,238,'{\"en\":\"No\",\"de\":\"Nein\",\"it\":\"No\",\"fr\":\"Non\",\"ar\":\"لا\"}',NULL,3,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(414,238,'{\"en\":\"Still being prepared