INSERT INTO `serves_page_forms` VALUES (1,1,'{\"de\": \"Buchen Sie einen Umzug mit 30% Rabatt – zeitlich begrenztes Angebot!\", \"en\": \"Book a Moving Service with 30% Off – Limited Time Offer!\", \"fr\": \"Réservez un déménagement avec 30% de réduction – offre limitée\", \"it\": \"Prenota un trasloco con il 30% di sconto – offerta a tempo limitato!\"}','uploads//images/1749714576329.jpg','{\"en\":\"<p><span>Need a safe and fast moving service? Grab our limited-time offer now and enjoy a smooth, stress-free move.</span></p>\",\"de\":\"<p><span>Brauchen Sie einen sicheren und schnellen Umzugsservice? Nutzen Sie unser zeitlich begrenztes Angebot und genießen Sie einen reibungslosen Umzug ohne Stress.</span></p>\",\"it\":\"<p><span>Hai bisogno di un servizio di trasloco sicuro e veloce? Approfitta della nostra offerta a tempo limitato e goditi un trasloco comodo e senza stress.</span></p>\",\"fr\":\"<p><span>Besoin d’un déménagement sûr et rapide ? Profitez de notre offre spéciale maintenant, pour un trajet confortable et sans stress.</span></p>\"}','{\"de\": \"umzug service, hausumzug, rabatt umzug, günstiger umzug\", \"en\": \"moving service, house moving, discounted moving, cheap relocation\", \"fr\": \"service déménagement, déménagement maison, déménagement discount, promo déménagement\", \"it\": \"servizio trasloco, trasloco casa, trasloco scontato, promozione trasloco\"}','{\"de\": \"offers-Umzug\", \"en\": \"offers-moving\", \"fr\": \"offers-Déménagement\", \"it\": \"offers-Trasloco\"}','{\"de\": \"Umzug & Reinigung in einem Paket – bester Preis\", \"en\": \"Moving Service with 30% Off – Limited-Time Offer\", \"fr\": \"Déménagement avec 30% de réduction – offre temporaire\", \"it\": \"Servizio di trasloco con il 30% di sconto – offerta temporanea\"}','{\"de\": \"Sichern Sie sich jetzt 30% Rabatt auf unseren Premium-Umzugsservice – nur für kurze Zeit verfügbar! Buchen Sie noch heute!\", \"en\": \"Enjoy a 30% discount on premium moving service for a limited time only. Book now before this offer runs out!\", \"fr\": \"Profitez d\'une réduction de 30% sur notre service de déménagement premium pendant une durée limitée. Réservez maintenant avant que l\'offre ne soit terminée\", \"it\": \"Goditi uno sconto del 30% sul nostro servizio di trasloco premium solo per un periodo limitato. Prenota ora prima che l’offerta scada!\"}','2025-05-11 11:04:26','2025-06-12 09:49:36'),(2,2,'{\"de\": \"Exklusives Paket: Umzug und Reinigung in einem Deal\", \"en\": \"Special Bundle: Home Moving & Cleaning in One Deal\", \"fr\": \"Offre exclusive : Déménagement + nettoyage en une seule fois\", \"it\": \"Pacchetto esclusivo: Trasloco e pulizia in un’unica soluzione\"}','uploads//images/1749714887509.jpg','{\"en\":\"<p><span>Don’t miss this exclusive bundle! Get home moving and deep cleaning in one seamless package – faster, easier, and more affordable.</span></p>\",\"de\":\"<p><span>Lassen Sie dieses exklusive Paket nicht verpassen! Kombinieren Sie Ihren Umzug mit einer professionellen Reinigung – schnell, einfach und günstiger als je zuvor.</span></p>\",\"it\":\"<p><span>Non perdere questa occasione esclusiva! Combina trasloco e pulizia completa in un\'unica soluzione – più veloce, facile ed economica che mai.</span></p>\",\"fr\":\"<p><span>Ne manquez pas cette offre exclusive : combinez déménagement et nettoyage complet en une seule étape – plus rapide, plus simple et plus abordable.</span></p>\"}','{\"de\": \"umzug reinigung, hausreinigung, paket deal, sonderangebot\", \"en\": \"home moving, house cleaning, bundle deal, special offer\", \"fr\": \"déménagement nettoyage, service ménage, pack spécial, offre exclusif\", \"it\": \"trasloco pulizia, servizio pulizia, pacchetto speciale, offerta esclusiva\"}','{\"de\": \"Umzug-Reinigung\", \"en\": \"moving-cleaning\", \"fr\": \"Déménagement-Nettoyage\", \"it\": \"Trasloco-Pulizia\"}','{\"de\": \"Umzug & Reinigung in einem Paket – bester Preis | kompassumzug\", \"en\": \"Home Moving & Cleaning Bundle – Best Price Guaranteed | kompassumzug\", \"fr\": \"Déménagement et nettoyage combinés – Meilleur prix garanti | kompassumzug\", \"it\": \"Trasloco e pulizia insieme – miglior prezzo garantito | kompassumzug\"}','{\"de\": \"Kombinieren Sie Umzug und Reinigung in einem exklusiven Paket – schnell, zuverlässig und kosteneffizient! Greifen Sie zu, solange das Angebot gilt!\", \"en\": \"Combine home moving and professional cleaning in one exclusive deal. Fast, reliable, and cost-effective – don’t miss out!\", \"fr\": \"Combine le déménagement et le nettoyage en un seul forfait exclusif. Rapide, fiable et économique – ne laissez pas passer cette opportunité !\", \"it\": \"Combina trasloco e pulizia in un’unica offerta esclusiva. Veloce, affidabile ed economico – non lasciarti sfuggire questa opportunità!\"}','2025-05-12 13:55:43','2025-06-12 09:54:47'),(3,3,'{\"de\": \"Hausreinigung mit bis zu 40% Rabatt – exklusiv\", \"en\": \"Deep Cleaning at Up to 40% Off – Exclusive Deal\", \"fr\": \"Nettoyage complet à -40% – Profitez-en vite\", \"it\": \"Pulizia profonda fino al 40% di sconto – offerta speciale\"}','uploads//images/1749714931579.jpg','{\"en\":\"<p><span>Want a spotless home without the hassle? Take advantage of our exclusive discount on comprehensive cleaning services for houses and apartments. Book before it’s gone</span></p>\",\"de\":\"<p><span>Ein sauberes Zuhause war noch nie so einfach! Profitieren Sie von unserem exklusiven Rabatt auf umfassende Reinigungsdienste für Häuser und Wohnungen. Buchen Sie jetzt, bevor das Angebot endet</span></p>\",\"it\":\"<p><span>Una casa pulita non è mai stata così semplice! Approfitta dello sconto esclusivo sui nostri servizi di pulizia completa per case e appartamenti. Prenota prima che l’offerta termini</span></p>\",\"fr\":\"<p><span>Un logement propre sans effort  Bénéficiez d’une remise exclusive sur nos services de nettoyage complet pour maisons et appartements. Réservez avant la fin de l’offre </span></p>\"}','{\"de\": \"hausreinigung, wohnungsreinigung, tiefenreinigung, reinigungsangebot\", \"en\": \"house cleaning, apartment cleaning, deep cleaning, discount service\", \"fr\": \"nettoyage maison, nettoyage appartement, service nettoyage, promo nettoyage\", \"it\": \"pulizia case, pulizia appartamenti, pulizia profonda, offerte pulizia\"}','{\"de\": \"offers-Reinigung\", \"en\": \"offers-cleaning\", \"fr\": \"offers-Nettoyage\", \"it\": \"offers-Pulizia\"}','{\"de\": \"Professionelle Reinigung mit bis zu 40% Rabatt |kompassumzug\", \"en\": \"Deep House Cleaning with Up to 40% Discount |kompassumzug\", \"fr\": \"Nettoyage professionnel avec jusqu’à 40% de réduction |kompassumzug\", \"it\": \"Pulizia professionale con sconto fino al 40% |kompassumzug\"}','{\"de\": \"Profi-Reinigungsservice mit bis zu 40% Rabatt! Exklusives Angebot für hochwertige Reinigungsleistungen – buchen Sie jetzt, bevor es vorbei ist!\", \"en\": \"Get your home professionally cleaned at up to 40% off! Limited-time offer for high-quality cleaning services. Book now!\", \"fr\": \"Faites nettoyer votre maison par des professionnels avec une remise de jusqu’à 40% ! Offre limitée pour des services de qualité. Réservez dès maintenant !\", \"it\": \"Servizio di pulizia professionale con sconti fino al 40%! Offerta limitata per servizi di alta qualità. Prenota subito!\"}','2025-05-12 14:01:38','2025-06-12 09:55:31'),(4,3,'{\"de\": \"Hausreinigung mit bis zu 40% Rabatt – exklusiv\", \"en\": \"Deep Cleaning at Up to 40% Off – Exclusive Deal\", \"fr\": \"Nettoyage complet à -40% – Profitez-en vite\", \"it\": \"Pulizia profonda fino al 40% di sconto – offerta speciale\"}','uploads//images/1747051299781.jpg','{\"en\":\"<p><span>Want a spotless home without the hassle? Take advantage of our exclusive discount on comprehensive cleaning services for houses and apartments. Book before it’s gone</span></p>\",\"de\":\"<p><span>Ein sauberes Zuhause war noch nie so einfach! Profitieren Sie von unserem exklusiven Rabatt auf umfassende Reinigungsdienste für Häuser und Wohnungen. Buchen Sie jetzt, bevor das Angebot endet</span></p>\",\"it\":\"<p><span>Una casa pulita non è mai stata così semplice! Approfitta dello sconto esclusivo sui nostri servizi di pulizia completa per case e appartamenti. Prenota prima che l’offerta termini</span></p>\",\"fr\":\"<p><span>Un logement propre sans effort  Bénéficiez d’une remise exclusive sur nos services de nettoyage complet pour maisons et appartements. Réservez avant la fin de l’offre </span></p>\"}','{\"de\": \"hausreinigung, wohnungsreinigung, tiefenreinigung, reinigungsangebot\", \"en\": \"house cleaning, apartment cleaning, deep cleaning, discount service\", \"fr\": \"nettoyage maison, nettoyage appartement, service nettoyage, promo nettoyage\", \"it\": \"pulizia case, pulizia appartamenti, pulizia profonda, offerte pulizia\"}','{\"de\": \"offers-Reinigung-\", \"en\": \"offers-cleaning-\", \"fr\": \"offers-Nettoyage-\", \"it\": \"offers-Pulizia\"}','{\"de\": \"Professionelle Reinigung mit bis zu 40% Rabatt |kompassumzug\", \"en\": \"Deep House Cleaning with Up to 40% Discount |kompassumzug\", \"fr\": \"Nettoyage professionnel avec jusqu’à 40% de réduction |kompassumzug\", \"it\": \"Pulizia professionale con sconto fino al 40% |kompassumzug\"}','{\"de\": \"Profi-Reinigungsservice mit bis zu 40% Rabatt! Exklusives Angebot für hochwertige Reinigungsleistungen – buchen Sie jetzt, bevor es vorbei ist!\", \"en\": \"Get your home professionally cleaned at up to 40% off! Limited-time offer for high-quality cleaning services. Book now!\", \"fr\": \"Faites nettoyer votre maison par des professionnels avec une remise de jusqu’à 40% ! Offre limitée pour des services de qualité. Réservez dès maintenant !\", \"it\": \"Servizio di pulizia professionale con sconti fino al 40%! Offerta limitata per servizi di alta qualità. Prenota subito!\"}','2025-05-12 14:01:39','2025-05-12 14:01:39'),(5,3,'{\"de\": \"Hausreinigung mit bis zu 40% Rabatt – exklusiv\", \"en\": \"Deep Cl