INSERT INTO `type_ditali_services` VALUES (16,1,'{\"en\":\"uploads\\/\\/images\\/1767218309576.png\",\"de\":\"uploads\\/\\/images\\/1767218309195.png\",\"it\":\"uploads\\/\\/images\\/1767218309149.png\",\"fr\":\"uploads\\/\\/images\\/1767218309670.png\",\"ar\":\"uploads\\/\\/images\\/1767218309951.png\"}','{\"de\":\"Wir planen und führen Bau- und Renovierungsprojekte mit Präzision und Professionalität für beste Ergebnisse durch.\",\"en\":\"We plan and execute construction and renovation projects with precision and professionalism for guaranteed results.\",\"fr\":\"Nous planifions et réalisons vos projets de construction et de rénovation avec précision et professionnalisme pour des résultats garantis.\",\"it\":\"Pianifichiamo e realizziamo progetti di costruzione e ristrutturazione con precisione e professionalità per risultati garantiti.\",\"ar\":\"نخطط وننفذ مشاريع البناء والترميم بدقة واحترافية، لتضمن أفضل النتائج\"}','{\"en\":\"uploads\\/\\/images\\/1767218309135.png\",\"de\":\"uploads\\/\\/images\\/1767218309529.png\",\"it\":\"uploads\\/\\/images\\/1767218309975.png\",\"fr\":\"uploads\\/\\/images\\/1767218309184.png\",\"ar\":\"uploads\\/\\/images\\/1767218309876.png\"}','{\"de\":\"Unsere Merkmale\",\"en\":\"Our Features\",\"fr\":\"Nos fonctionnalités\",\"it\":\"Le nostre caratteristiche\",\"ar\":\"ميزاتنا\"}',NULL,'{\"de\":\"Bau & Sanierung\",\"en\":\"Construction & Renovation\",\"fr\":\"Construction & Rénovation\",\"it\":\"Costruzione & Ristrutturazione\",\"ar\":\"العربي: البناء والترميم\"}','{\"de\":\"<p>Umfassende Leistungen für Bau, Erweiterung, Renovierung und Abriss – alles aus einer Hand.</p>\",\"en\":\"<p> Comprehensive construction, extension, renovation, and demolition services with end-to-end management.</p>\",\"fr\":\"<p>Services complets de construction, d’extension, de rénovation et de démolition avec gestion intégrale.</p>\",\"it\":\"<p>Servizi completi di costruzione, ampliamento, ristrutturazione e demolizione con gestione totale.</p>\",\"ar\":\"<p>خدمات شاملة لأعمال البناء، التوسعة، الترميم، والهدم مع إدارة كاملة للعملية من البداية للنهاية.</p>\"}','{\"de\":\"Nützliche Tipps & Tricks\",\"en\":\"Helpful Tips & Tricks\",\"fr\":\"Astuces et conseils utiles\",\"it\":\"Consigli e trucchi utili\",\"ar\":\"نصائح وحيل مفيدة\"}','{\"de\":\"Sehen Sie sich unsere Tipps für einen reibungslosen und stressfreien Umzug an\",\"en\":\"Check out our tips for a smooth and stress-free move.\",\"fr\":\"Découvrez nos conseils pour un déménagement fluide et sans stress\",\"it\":\"Dai un\'occhiata ai nostri consigli per un trasloco semplice e senza stress\",\"ar\":\"اطلع على نصائحنا لعملية نقل سلسة وخالية من التوتر.\"}','uploads//images/1741697647333.png',NULL,'{\"de\":\"Bau | Renovierung | Baudienstleistungen | Hausrenovierung | Umbau | vertrauenswürdiger Auftragnehmer | Renovierungsprojekte | Gebäudeinstandsetzung\",\"en\":\"construction | renovation | building services | home renovation | remodeling | trusted contractor | renovation projects | building repair | professional construction\",\"fr\":\"construction | rénovation | services de construction | rénovation de maison | réaménagement | entrepreneur de confiance | projets de rénovation | réparation de bâtiments\",\"it\":\"costruzione | ristrutturazione | servizi di costruzione | ristrutturazione casa | remodel | partner affidabile | progetti di ristrutturazione | riparazione edifici\",\"ar\":\"بناء | ترميم | خدمات بناء | تجديد المنازل | صيانة المباني | مقاول موثوق | مشاريع ترميم | تحسين المنزل\"}','{\"de\":\"Bau- und Renovierungsdienste von Ihrem vertrauenswürdigen Partner für höchste Qualität und professionelle Ergebnisse.\",\"en\":\"Construction and renovation services from your trusted partner, delivering top quality and professional results.\",\"fr\":\"Services de construction et de rénovation par votre partenaire de confiance, garantissant une qualité optimale et des résultats professionnels.\",\"it\":\"Servizi di costruzione e ristrutturazione dal tuo partner di fidu