INSERT INTO `type_features` VALUES (7,1,'uploads//images/1737624056810.png','{\"de\":\"Hochwertige Materialien\",\"en\":\"High-Quality Materials\",\"fr\":\"Matériaux de haute qualité\",\"it\":\"Materiali di alta qualità\",\"ar\":\"جودة المواد المستخدمة\"}','{\"de\":\"Wir gewährleisten die Verwendung hochwertiger Materialien für langlebige und elegante Bau- und Renovierungsergebnisse.\",\"en\":\"We ensure the use of top-quality materials for durable and elegant construction and renovation results.\",\"fr\":\"Nous garantissons l\'utilisation de matériaux de haute qualité pour des résultats durables et élégants.\",\"it\":\"Garantiamo l\'uso di materiali di alta qualità per risultati di costruzione e ristrutturazione duraturi ed eleganti.\",\"ar\":\"نضمن استخدام أفضل المواد عالية الجودة لضمان متانة ومظهر أنيق لجميع أعمال البناء والترميم.\"}','2024-12-26 12:10:41','2025-12-18 22:01:55'),(9,1,'uploads//images/1737624364361.jpg','{\"de\":\"Termingerechte Lieferung\",\"en\":\"Timely Delivery\",\"fr\":\"Livraison ponctuelle\",\"it\":\"Consegna puntuale\",\"ar\":\"الالتزام بالمواعيد\"}','{\"de\":\"Wir halten Projektpläne genau ein, um Bau- und Renovierungsarbeiten pünktlich zu liefern.\",\"en\":\"We strictly follow project schedules to deliver construction and renovation works on time.\",\"fr\":\"Nous respectons strictement les calendriers pour livrer les travaux de construction et de rénovation à temps.\",\"it\":\"Rispettiamo rigorosamente i programmi di progetto per consegnare i lavori di costruzione e ristrutturazione in tempo.\",\"ar\":\"نحترم جداول المشروع بدقة لتسليم أعمال البناء والترميم في الوقت المحدد دون تأخير.\"}','2025-01-02 15:21:19','2025-12-18 22:05:06'),(14,2,'uploads//images/1737648476241.png','{\"de\":\"Moderner Innenausbau\",\"en\":\"Modern Interior Finishing\",\"fr\":\"Finitions intérieures modernes\",\"it\":\"Finiture interne moderne\",\"ar\":\"تشطيب داخلي عصري باحتراف\"}','{\"de\":\"Wir vermitteln Fachkräfte für hochwertigen Innenausbau in Wohn- und Geschäftsräumen.\",\"en\":\"We connect you with skilled professionals for high-quality interior finishing in homes and offices.\",\"fr\":\"Nous vous mettons en relation avec des professionnels pour des finitions intérieures de haute qualité.\",\"it\":\"Ti mettiamo in contatto con professionisti qualificati per finiture interne di alta qualità.\",\"ar\":\"نربطك بحرفيين متخصصين لتنفيذ أعمال التشطيب الداخلي بجودة عالية تناسب المنازل والمكاتب.\"}','2025-01-23 16:07:56','2026-01-04 23:05:17'),(18,2,'uploads//images/1737673461629.jpg','{\"de\":\"Strukturierte Renovierung\",\"en\":\"Organized Renovation Process\",\"fr\":\"Rénovation organisée\",\"it\":\"Ristrutturazione organizzata\",\"ar\":\"تجديد منظم بدون فوضى\"}','{\"de\":\"Renovierungsarbeiten mit klaren Abläufen und guter Koordination\",\"en\":\"Renovation work carried out with clear steps and proper coordination for precise results.\",\"fr\":\"Travaux de rénovation réalisés avec des étapes claires et une bonne coordination\",\"it\":\"Lavori di ristrutturazione eseguiti con passaggi chiari e coordinati\",\"ar\":\"تنفيذ أعمال التجديد بخطوات واضحة وتنسيق كامل لتحقيق نتائج دقيقة وفي الوقت المحدد.\"}','2025-01-23 23:04:21','2026-01-04 23:07:22');
/*!40000 ALTER TABLE `type_features` ENABLE KEYS */;
