  `max_files` int DEFAULT NULL,
  `max_file_size` int DEFAULT NULL,
  `order` int NOT NULL DEFAULT '0',
  `parent_question_id` bigint unsigned DEFAULT NULL,
  `parent_option_id` bigint unsigned DEFAULT NULL,
