  CONSTRAINT `type_questions_parent_question_id_foreign` FOREIGN KEY (`parent_question_id`) REFERENCES `type_questions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `type_questions_type_id_foreign` FOREIGN KEY (`type_id`) REFERENCES `types` (`id`) ON DELETE CASCADE
