INSERT INTO `type_questions` VALUES (232,30,'{\"en\":\"What work needs to be carried out?\",\"de\":\"Welche Arbeiten sollen durchgeführt werden?\",\"it\":\"Quali lavori devono essere eseguiti?\",\"fr\":\"Quels travaux doivent être réalisés ?\",\"ar\":\"ما الأعمال المطلوب تنفيذها؟\"}','multi_choice',1,1,0,NULL,NULL,NULL,1,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(233,30,'{\"en\":\"Please specify\",\"de\":\"Bitte angeben\",\"it\":\"Specificare\",\"fr\":\"Veuillez préciser\",\"ar\":\"يرجى التحديد\"}','text',0,1,0,NULL,NULL,NULL,1,232,392,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(234,30,'{\"en\":\"What type of construction project is it?\",\"de\":\"Um welche Art von Bauvorhaben handelt es sich?\",\"it\":\"Di che tipo di progetto edilizio si tratta?\",\"fr\":\"De quel type de projet de construction s’agit-il ?\",\"ar\":\"ما نوع مشروع البناء؟\"}','single_choice',1,1,0,NULL,NULL,NULL,2,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(235,30,'{\"en\":\"Please specify\",\"de\":\"Bitte angeben\",\"it\":\"Specificare\",\"fr\":\"Veuillez préciser\",\"ar\":\"يرجى التحديد\"}','text',0,1,0,NULL,NULL,NULL,1,234,398,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(236,30,'{\"en\":\"Approximately how large is the planned construction area?\",\"de\":\"Wie groß ist die geplante Baufläche ungefähr?\",\"it\":\"Quanto è grande approssimativamente la superficie di costruzione prevista?\",\"fr\":\"Quelle est approximativement la superficie de construction prévue ?\",\"ar\":\"ما المساحة التقريبية لأعمال البناء المخطط لها؟\"}','single_choice',1,1,0,NULL,NULL,NULL,3,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(237,30,'{\"en\":\"What is the current status of the construction project?\",\"de\":\"In welchem Zustand befindet sich das Bauvorhaben aktuell?\",\"it\":\"Qual è lo stato attuale del progetto edilizio?\",\"fr\":\"Quel est l’état actuel du projet de construction ?\",\"ar\":\"ما الوضع الحالي لمشروع البناء؟\"}','single_choice',1,1,0,NULL,NULL,NULL,4,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(238,30,'{\"en\":\"Are construction plans or technical drawings available?\",\"de\":\"Liegen Baupläne oder technische Zeichnungen vor?\",\"it\":\"Sono disponibili progetti o disegni tecnici?\",\"fr\":\"Des plans de construction ou des dessins techniques sont-ils disponibles ?\",\"ar\":\"هل توجد مخططات بناء أو رسومات فنية؟\"}','single_choice',1,1,0,NULL,NULL,NULL,5,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(239,30,'{\"en\":\"Is a required building permit available?\",\"de\":\"Ist eine erforderliche Baugenehmigung vorhanden?\",\"it\":\"È disponibile l’eventuale permesso di costruire necessario?\",\"fr\":\"Le permis de construire requis est-il disponible ?\",\"ar\":\"هل تصريح البناء المطلوب متوفر؟\"}','single_choice',1,1,0,NULL,NULL,NULL,6,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(240,30,'{\"en\":\"Who should provide the required building materials?\",\"de\":\"Wer soll die benötigten Baumaterialien bereitstellen?\",\"it\":\"Chi deve fornire i materiali da costruzione necessari?\",\"fr\":\"Qui doit fournir les matériaux de construction nécessaires ?\",\"ar\":\"من سيقوم بتوفير مواد البناء المطلوبة؟\"}','single_choice',1,1,0,NULL,NULL,NULL,7,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(241,30,'{\"en\":\"When would you like the job to be carried out?\",\"de\":\"Wann möchten Sie den Auftrag ausführen lassen?\",\"it\":\"Quando desidera che venga eseguito il lavoro?\",\"fr\":\"Quand souhaitez-vous faire réaliser les travaux ?\",\"ar\":\"متى ترغب في تنفيذ الطلب؟\"}','single_choice',1,1,0,NULL,NULL,NULL,8,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(242,30,'{\"en\":\"Would you like to add photos or documents?\",\"de\":\"Möchten Sie Fotos oder Unterlagen hinzufügen?\",\"it\":\"Desidera aggiungere foto o documenti?\",\"fr\":\"Souhaitez-vous ajouter des photos ou des documents ?\",\"ar\":\"هل ترغب في إرفاق صور أو مستندات؟\"}','single_choice',0,1,1,'jpg,jpeg,png,pdf,heic,webp',10,10240,9,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(243,30,'{\"en\":\"Describe your request.\",\"de\":\"Beschreiben Sie Ihre Anfrage.\",\"it\":\"Descriva la sua richiesta.\",\"fr\":\"Décrivez votre demande.\",\"ar\":\"صف طلبك.\"}','text',1,1,0,NULL,NULL,NULL,10,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(244,29,'{\"en\":\"What type of earthwork or excavation is required?\",\"de\":\"Welche Erd- oder Baggerarbeiten werden benötigt?\",\"it\":\"Quali lavori di terra o scavo sono necessari?\",\"fr\":\"Quels travaux de terrassement ou d’excavation sont nécessaires ?\",\"ar\":\"ما نوع أعمال الحفر أو الأعمال الترابية المطلوبة؟\"}','multi_choice',1,1,0,NULL,NULL,NULL,1,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(245,29,'{\"en\":\"Please specify\",\"de\":\"Bitte angeben\",\"it\":\"Specificare\",\"fr\":\"Veuillez préciser\",\"ar\":\"يرجى التحديد\"}','text',0,1,0,NULL,NULL,NULL,1,244,437,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(246,29,'{\"en\":\"What is the excavation for?\",\"de\":\"Wofür werden die Erdarbeiten benötigt?\",\"it\":\"A cosa servono i lavori di scavo?\",\"fr\":\"À quoi servent les travaux d’excavation ?\",\"ar\":\"ما الغرض من أعمال الحفر؟\"}','single_choice',1,1,0,NULL,NULL,NULL,2,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(247,29,'{\"en\":\"Please specify\",\"de\":\"Bitte angeben\",\"it\":\"Specificare\",\"fr\":\"Veuillez préciser\",\"ar\":\"يرجى التحديد\"}','text',0,1,0,NULL,NULL,NULL,1,246,444,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(248,29,'{\"en\":\"Approximately how large is the work area?\",\"de\":\"Wie groß ist die Arbeitsfläche ungefähr?\",\"it\":\"Quanto è grande circa l’area di lavoro?\",\"fr\":\"Quelle est approximativement la surface de travail ?\",\"ar\":\"ما مساحة منطقة العمل تقريبًا؟\"}','single_choice',1,1,0,NULL,NULL,NULL,3,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(249,29,'{\"en\":\"Approximately how deep must the excavation be?\",\"de\":\"Wie tief muss ungefähr ausgehoben werden?\",\"it\":\"Quanto deve essere profondo circa lo scavo?\",\"fr\":\"Quelle profondeur d’excavation est approximativement nécessaire ?\",\"ar\":\"ما عمق الحفر المطلوب تقريبًا؟\"}','single_choice',0,1,0,NULL,NULL,NULL,4,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(250,29,'{\"en\":\"What type of soil is on site?\",\"de\":\"Welche Bodenart ist vor Ort vorhanden?\",\"it\":\"Che tipo di terreno è presente sul posto?\",\"fr\":\"Quel type de sol est présent sur place ?\",\"ar\":\"ما نوع التربة الموجودة في الموقع؟\"}','single_choice',0,1,0,NULL,NULL,NULL,5,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(251,29,'{\"en\":\"Should excavated soil or material be removed from the site?\",\"de\":\"Soll Aushub oder Erdmaterial abtransportiert werden?\",\"it\":\"Il terreno scavato deve essere trasportato via?\",\"fr\":\"Les terres excavées doivent-elles être évacuées ?\",\"ar\":\"هل يجب نقل التربة أو مخلفات الحفر خارج الموقع؟\"}','single_choice',1,1,0,NULL,NULL,NULL,6,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(252,29,'{\"en\":\"How accessible is the work area for machinery?\",\"de\":\"Wie gut ist die Arbeitsfläche für Maschinen erreichbar?\",\"it\":\"Quanto è accessibile l’area di lavoro per i macchinari?\",\"fr\":\"Dans quelle mesure la zone de travail est-elle accessible aux engins ?\",\"ar\":\"ما مدى سهولة وصول المعدات إلى موقع العمل؟\"}','single_choice',1,1,0,NULL,NULL,NULL,7,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(253,29,'{\"en\":\"When would you like the job to be carried out?\",\"de\":\"Wann möchten Sie den Auftrag ausführen lassen?\",\"it\":\"Quando desidera che venga eseguito il lavoro?\",\"fr\":\"Quand souhaitez-vous faire réaliser les travaux ?\",\"ar\":\"متى ترغب في تنفيذ الطلب؟\"}','single_choice',1,1,0,NULL,NULL,NULL,8,NULL,NULL,'2026-10-13 06:56:43','2026-10-13 06:56:43'),(254,29,'{\"en\":\"Would you like to add photos or documents?\",\"de\":\"Möchten Sie Fotos oder Unterlagen hinzufügen?\",\"it\":\"Desidera aggiungere foto 