INSERT INTO `types` VALUES (1,NULL,'{\"en\":\"Construction, structural work & major building projects\",\"de\":\"Bau, Rohbau & größere Bauvorhaben\",\"fr\":\"Construction, gros œuvre & grands projets de bâtiment\",\"it\":\"Costruzione, opere strutturali e grandi progetti edilizi\",\"ar\":\"البناء، الهيكل الإنشائي ومشاريع البناء الكبرى\"}',1.00,1,1,'2025-02-12 16:31:30','2026-10-13 06:58:49'),(2,NULL,'{\"en\":\"Interior finishing & renovation\",\"fr\":\"Aménagement intérieur & rénovation\",\"de\":\"Innenausbau & Renovierung\",\"it\":\"Finiture d\'interni e ristrutturazione\",\"ar\":\"التشطيبات الداخلية والتجديد\"}',1.00,3,1,'2025-02-12 16:31:35','2026-10-13 07:04:04'),(3,NULL,'{\"en\":\"Sanitary, heating & climate\",\"de\":\"Sanitär, Heizung & Klima\",\"fr\":\"Sanitaire, chauffage & climatisation\",\"it\":\"Sanitari, riscaldamento e climatizzazione\",\"ar\":\"السباكة، التدفئة والتكييف\"}',1.00,4,1,'2025-02-12 16:31:39','2026-10-15 13:11:38'),(21,NULL,'{\"en\":\"Electrical & smart home\",\"de\":\"Elektro & Smart Home\",\"it\":\"Elettrico e Smart Home\",\"fr\":\"Électricité & maison intelligente\",\"ar\":\"الكهرباء والمنزل الذكي\"}',1.00,5,1,'2025-12-18 21:19:15','2026-10-15 13:11:39'),(22,NULL,'{\"en\":\"Gardening & landscaping\",\"de\":\"Garten- & Landschaftsbau\",\"it\":\"Giardinaggio e paesaggistica\",\"fr\":\"Jardinage & aménagement paysager\",\"ar\":\"أعمال الحدائق وتنسيق المواقع\"}',1.00,6,1,'2025-12-18 21:21:04','2026-10-15 10:17:50'),(23,NULL,'{\"en\":\"Furniture, kitchens & assembly work\",\"de\":\"Möbel-, Küchen- & Montagearbeiten\",\"it\":\"Mobili, cucine e lavori di montaggio\",\"fr\":\"Meubles, cuisines & travaux de montage\",\"ar\":\"أثاث، مطابخ وأعمال تركيب\"}',1.00,8,1,'2025-12-18 21:22:34','2026-10-15 10:24:29'),(24,NULL,'{\"en\":\"Moving, transport & clearance\",\"de\":\"Umzug, Transport & Entrümpelung\",\"it\":\"Traslochi, trasporti e sgomberi\",\"fr\":\"Déménagement, transport & débarras\",\"ar\":\"نقل، شحن وإخلاء\"}',25.00,9,1,'2025-12-18 21:24:07